contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // params: amount to attempt to burn, and a flag indicating whether to try to make this contract the owner
    function run(uint256 burnAmount, bool tryClaimOwner) public payable {
        require(true);

        // Observe initial public values
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 myBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        // Optionally attempt to become owner by calling owned() if this contract is already the msg.sender owner in c's constructor scenario.
        // owned() has onlyOwner modifier so it will revert unless this contract is already owner; we'll ignore revert.
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            // ignore
        } else {
            // if succeeds, owner may have changed to address(this)
        }

        // Re-read owner after attempted claim
        address ownerAfterClaim = c.owner(); if (__ESBMC_reverted()) return;
        bool amOwner = (ownerAfterClaim == address(this));

        // Attempt burn and record whether it reverted
        bool reverted;
        c.burn(burnAmount); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read post-call observable state
        uint256 totalAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 myBalAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        // General invariant to hold for all inputs:
        // - If we are not owner, burn must revert and observable values unchanged.
        // - If we are owner, then burn reverts iff myBalBefore < burnAmount; if it succeeds, my balance and totalSupply both decrease by exactly burnAmount.
        bool ruleNotOwner = (!amOwner) ? (reverted && totalAfter == totalBefore && myBalAfter == myBalBefore) : true;
        bool ruleOwner;
        if (amOwner) {
            if (myBalBefore < burnAmount) {
                // must revert and no observable change
                ruleOwner = (reverted && totalAfter == totalBefore && myBalAfter == myBalBefore);
            } else {
                // must succeed and both decrease by burnAmount
                ruleOwner = (!reverted && totalAfter + burnAmount == totalBefore && myBalAfter + burnAmount == myBalBefore);
            }
        } else {
            ruleOwner = true;
        }

        assert(ruleNotOwner && ruleOwner);
    }

    receive() external payable { }
}

